static inline int ppg_stress_predict(float ppg_raw) {
    size_t low = 0, high = PPG_STRESS_REGION_COUNT - 1;
    while (low < high) {
        const size_t mid = low + (high - low) / 2;
        if (ppg_raw < (float)ppg_stress_boundaries[mid]) high = mid;
        else low = mid + 1;
    }
    return ppg_stress_region_labels[low];
}

static inline const char* ppg_stress_label_name(int label) {
    return label == PPG_STRESS_STRESSED ? "Stressed" : "Relax";
}

